  const b = j.body;
  const config = j.config;
  const fail = (c, m) => ctx.errors.push({ code: c, message: m });
  const done = (step) => { ctx.steps.push(step); return { json: { ...j, ctx } }; };

  const accountId = typeof b.account_id === 'string' ? b.account_id.trim() : '';
  const channelId = typeof b.channel_id === 'string' ? b.channel_id.trim() : '';

