    timezone: typeof b.timezone === 'string' ? b.timezone.trim() : null,
    scheduled_at: b.scheduled_at === undefined ? null : b.scheduled_at,
    media_count: Array.isArray(b.media) ? b.media.length : 0,
  };

  if (!accountId || !channelId) return done('05_resolution_skipped');

  const account = config.accounts.find((a) => a.account_id === accountId);
  if (!account) { fail('ACCOUNT_NOT_FOUND', 'The requested account does not exist.'); return done('05_account_not_found'); }
  if (account.active === false) { fail('ACCOUNT_NOT_FOUND', 'The requested account exists but is not active.'); return done('05_account_inactive'); }

  const channel = account.channels.find((c) => c.channel_id === channelId);
  if (!channel) {
    const owner = config.accounts.find((a) => a.channels.some((c) => c.channel_id === channelId));
    if (owner) {
      fail('CHANNEL_NOT_BELONG_TO_ACCOUNT', 'Channel "' + channelId + '" belongs to account "' + owner.account_id + '", not "' + account.account_id + '".');
    } else {
      fail('CHANNEL_NOT_FOUND', 'Channel "' + channelId + '" does not exist.');
    }
    return done('05_channel_not_found');
  }
  if (channel.active === false) { fail('CHANNEL_INACTIVE', 'Channel "' + channel.channel_id + '" is not active.'); return done('05_channel_inactive'); }

  const platform = typeof channel.platform === 'string' ? channel.platform.trim().toLowerCase() : '';
  if (!config.supported_platforms.includes(platform)) {
    fail('INVALID_REQUEST', 'Platform "' + channel.platform + '" is not supported by this engine.');
    return done('05_platform_unsupported');
  }

  const profileId = typeof channel.buffer_profile_id === 'string' ? channel.buffer_profile_id.trim() : '';
  if (!profileId || /^(REAL_BUFFER_PROFILE_ID|REPLACE|TODO|CHANGEME|XXX)/i.test(profileId)) {
    fail('BUFFER_PROFILE_NOT_CONFIGURED', 'Channel "' + channel.channel_id + '" has no Buffer profile configured.');
    return done('05_profile_missing');
  }

  ctx.publishing_context = {
    account_id: account.account_id,
    account_name: account.account_name,
    channel_id: channel.channel_id,
    platform: platform,
    buffer_profile_id: profileId,
    buffer_channel_name: channel.buffer_channel_name || null,
  };
  ctx.steps.push('05_channel_resolved');
  logEvent({
    node: '05', event: 'channel_resolved', request_id: j.request_id,
    account_id: account.account_id, channel_id: channel.channel_id,
    platform: platform, buffer_profile_id: profileId,
  });
  return { json: { ...j, ctx } };
});

