// The n8n Code sandbox does not always expose the URL global, so this falls
// back to a pattern check when new URL() is unavailable.
function isFetchableHttpUrl(value) {
  if (typeof value !== 'string') return false;
  const v = value.trim();
  if (!v || !/^https?:\/\//i.test(v)) return false;
  try {
    const u = new URL(v);
    return (u.protocol === 'http:' || u.protocol === 'https:') && !!u.hostname;
  } catch (e) {
